<script setup>
import { computed, ref, watch } from 'vue'
const props = defineProps({ articles: Array, history: Array, currentArticle: Object, searching: Boolean, noteCount: Number }); defineEmits(['select','notes'])
const view = ref('articles'), expanded = ref(false)
const visible = computed(() => view.value === 'history' ? props.history : expanded.value || props.searching ? props.articles : props.articles.slice(0,5))
watch(() => props.searching, value => { if(value) view.value='articles' })
</script>
<template><div class="article-sidebar"><nav class="side-links" aria-label="个人书架"><button :class="{activeLink:view==='articles'}" @click="view='articles'">▤ <span>经典选读</span><small>{{ articles.length }}</small></button><button @click="$emit('notes')">✎ <span>我的笔记</span><small>{{ noteCount }}</small></button><button :class="{activeLink:view==='history'}" @click="view='history'">◷ <span>阅读历史</span><small>{{ history.length }}</small></button></nav><div class="side-title">{{ view==='history' ? '最近阅读' : searching ? '搜索结果' : '书架' }}<small>{{ visible.length }} 篇</small></div><button v-for="article in visible" :key="article.id" :aria-current="currentArticle.id===article.id?'page':undefined" :class="{active:currentArticle.id===article.id}" @click="$emit('select',article)"><strong>{{ article.title }}</strong><small>{{ article.author }} · {{ article.dynasty }}</small></button><div v-if="!visible.length" class="empty">{{ searching ? '没有匹配的篇目，试试作者或原文关键词。' : '暂无阅读记录' }}</div><button v-if="view==='articles' && !searching && articles.length>5" class="more-articles" @click="expanded=!expanded">{{ expanded ? '收起篇目 −' : '更多篇目 ＋' }}</button><p class="shelf-quote">文不离句，句不离篇，<br>篇不离人，人不离世。</p></div></template>
